content.css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent;
}
.snow-empty-state {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: var(--snow-radius, 18px);
  background: var(--snow-card-bg, #FFFFFF);
  color: var(--snow-ink-secondary, #6B7280);
  font-size: 12px;
  text-align: center;
  padding: 16px;
  border: 1px dashed rgba(0, 0, 0, 0.1);
}
.snow-empty-state .snow-empty-title {
  font-weight: 600;
  color: var(--snow-ink, #111827);
  font-size: 13px;
}
.snow-spline-host {
  --snow-primary: #007AFF;
  --snow-secondary: #AF52DE;
  --snow-tertiary: #00C7BE;
  --snow-positive: #34C759;
  --snow-warning: #FF9500;
  --snow-negative: #FF3B30;
  --snow-dark: #1C1C1E;
  --snow-ink: #111827;
  --snow-ink-secondary: #6B7280;
  --snow-ink-muted: #9CA3AF;
  --snow-on-dark: #FFFFFF;
  --snow-card-bg: #FFFFFF;
  --snow-border: #E5E7EB;
  --snow-radius: 18px;
  --snow-hover-bg: rgba(0, 122, 255, 0.055);
  --snow-hover-border: rgba(0, 122, 255, 0.14);
  --snow-selected-bg: rgba(0, 122, 255, 0.09);
  --snow-selected-border: rgba(0, 122, 255, 0.35);
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Display", "Inter", Roboto, Helvetica, Arial, sans-serif;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  user-select: none;
  -webkit-font-smoothing: antialiased;
  color: var(--snow-ink, #111827);
  padding: 0;
  margin: 0;
  background: transparent;
  overflow: hidden;
}
.snow-spline-host *,
.snow-spline-host *::before,
.snow-spline-host *::after {
  box-sizing: border-box;
}
.snow-spline-card {
  width: 100%;
  height: 100%;
  background: var(--snow-card-bg, #FFFFFF);
  border-radius: var(--snow-radius, 18px);
  padding: 18px 22px 14px 22px;
  display: flex;
  flex-direction: column;
  position: relative;
}
.snow-spline-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
  flex-shrink: 0;
}
.snow-spline-tabs {
  display: flex;
  align-items: center;
  gap: 18px;
  overflow-x: auto;
  scrollbar-width: none;
}
.snow-spline-tabs::-webkit-scrollbar {
  display: none;
}
.snow-spline-tab {
  position: relative;
  border: none;
  background: transparent;
  padding: 4px 2px 7px 2px;
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Display", "Inter", Roboto, Helvetica, Arial, sans-serif;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--snow-ink-muted, #9CA3AF);
  cursor: pointer;
  white-space: nowrap;
  transition: color 260ms cubic-bezier(0.22, 1, 0.36, 1), transform 220ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-spline-tab:hover {
  color: var(--snow-ink-secondary, #6B7280);
}
.snow-spline-tab.is-active {
  color: var(--snow-spline-accent, var(--snow-secondary, #AF52DE));
  font-weight: 600;
}
.snow-spline-tab.is-active::after {
  transform: scaleX(1);
  opacity: 1;
}
.snow-spline-tab::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  transform: scaleX(0);
  opacity: 0;
  transition: transform 280ms cubic-bezier(0.22, 1, 0.36, 1), opacity 240ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-spline-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.snow-pill-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 999px;
  border: 1px solid rgba(0, 0, 0, 0.04);
  background: rgba(0, 0, 0, 0.045);
  color: var(--snow-ink, #111827);
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Display", "Inter", Roboto, Helvetica, Arial, sans-serif;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 220ms cubic-bezier(0.22, 1, 0.36, 1), transform 180ms cubic-bezier(0.22, 1, 0.36, 1), border-color 220ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-pill-btn:hover {
  background: rgba(0, 0, 0, 0.075);
}
.snow-pill-btn:active {
  transform: scale(0.97);
}
.snow-pill-btn svg {
  opacity: 0.65;
}
.snow-spline-canvas-wrap {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
}
.snow-spline-svg {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}
.snow-spline-area {
  transition: opacity 380ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-spline-path {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.snow-spline-node {
  cursor: pointer;
  transition: r 220ms cubic-bezier(0.22, 1, 0.36, 1), stroke-width 220ms cubic-bezier(0.22, 1, 0.36, 1), opacity 220ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-spline-callout {
  position: absolute;
  pointer-events: none;
  background: var(--snow-dark, #1C1C1E);
  color: var(--snow-on-dark, #FFFFFF);
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.16);
  transform: translate(-50%, -100%);
  opacity: 0;
  transition: opacity 180ms cubic-bezier(0.22, 1, 0.36, 1), left 120ms cubic-bezier(0.22, 1, 0.36, 1), top 120ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-spline-callout.is-visible {
  opacity: 1;
}
.snow-spline-card.is-compact {
  padding: 12px 16px 10px 16px;
}
.snow-spline-card.is-compact .snow-spline-header {
  margin-bottom: 6px;
  gap: 8px;
}
.snow-spline-card.is-compact .snow-spline-tabs {
  gap: 12px;
}
.snow-spline-card.is-compact .snow-spline-tab {
  font-size: 12px;
  padding: 3px 2px 5px 2px;
}
.snow-spline-card.is-compact .snow-pill-btn {
  padding: 4px 10px;
  font-size: 11px;
  gap: 4px;
}
